// Assigns every species in Data/Monsters/species.json to one evolution line (bible v1.0, 30 groups) and a stage 1..9.
// Output: Data/Monsters/species_lines.json (a side file: species.json is generated by Tools/monster_gen and must not be edited by hand).
// Method per row: "name" (the species name equals a stage label or branch token), "keyword" (a name keyword picked the group,
// stage guessed from rank), "family" (the only/default group of its family, stage guessed from rank), "base" (a variant inherits its base).
// Rank to stage is a PLACEMENT GUESS for review only. Threat never comes from stage (bible section 6, Canon 4d).
// Usage: node Tools/bestiary/assign_species_lines.js   (deterministic)
const fs = require('fs');
const path = require('path');
const D = path.join(__dirname, '..', '..', 'Data', 'Monsters');
const species = JSON.parse(fs.readFileSync(path.join(D, 'species.json'), 'utf8'));
const lines = JSON.parse(fs.readFileSync(path.join(D, 'evolution_lines.json'), 'utf8')).groups;
const byId = Object.fromEntries(lines.map(l => [l.id, l]));
const norm = s => s.toLowerCase().replace(/[^a-z ]/g, ' ').replace(/\s+/g, ' ').trim();

// Ordered keyword rules per family: first match wins; the last entry for a family is its default.
const R = {
  goblinoid: [[/hobgoblin|legion/, 'hobgoblin_kind'], [/./, 'goblins']],
  orc_giant: [[/troll/, 'trolls'], [/ogre/, 'ogres'], [/giant|cyclops|titan|div|stone giant/, 'giants'], [/./, 'orcs']],
  draconic: [[/wyvern/, 'wyverns'], [/drake/, 'drakes'], [/./, 'dragons']],
  reptile: [[/hydra|serpent/, 'hydras'], [/./, 'basilisks_gorgons']],
  serpentfolk: [[/./, 'basilisks_gorgons']],
  aquatic: [[/./, 'aquatic']],
  undead: [[/vampire/, 'vampires'], [/./, 'undead']],
  vesperite: [[/./, 'vampires']],
  yokai: [[/./, 'spirits']],
  shadow: [[/./, 'spirits']],
  construct: [[/crystal/, 'crystals'], [/golem|doll|armor|colossus|titan|scarecrow|mimic/, 'golems'], [/./, 'automata']],
  elemental: [[/crystal|shard|gem/, 'crystals'], [/./, 'elementals']],
  insect: [[/spider|arachne|scorpion|weaver|web|tarantula/, 'arachnids'], [/./, 'insects']],
  killer_insect: [[/./, 'insects']],
  beast: [[/./, 'beasts']], lycan: [[/./, 'beasts']],
  avian: [[/./, 'avians']], plant: [[/./, 'plants']], slime: [[/./, 'slimes']],
  demon: [[/./, 'demons']],
  gremlin: [[/./, 'fae']], familiar: [[/./, 'fae']],
  chimera: [[/./, 'hybrids']], minotaur: [[/./, 'hybrids']], centaur: [[/./, 'hybrids']],
  aberration: [[/./, 'void']], headless: [[/./, 'void']]
};
// Names that belong to another group than their family default (checked first, by base name).
const OVERRIDE = [
  [/lich|death knight|bone dragon|no-life|mad magician|oathless/, 'undead'],
  [/vampire/, 'vampires'],
  [/oni warlord|kijin|goblin|gremlin/, null], // keep family default
  [/seraph/, 'celestials']
];
const STAGE_BY_RANK = { F: 1, E: 2, D: 3, C: 4, B: 5, A: 6, S: 7, SS: 8, SSS: 9, EX: 9 };
const rankStage = r => STAGE_BY_RANK[String(r).replace(/[+-]+$/, '')] || 1;

const stageIndex = {};
for (const l of lines) {
  stageIndex[l.id] = new Map(l.stages.map(s => [norm(s.label), s.stage]));
  for (const b of l.branches) for (const tok of b.split(/[:>]/).map(t => norm(t)).filter(Boolean)) if (!stageIndex[l.id].has(tok)) stageIndex[l.id].set(tok, null);
}
const spById = Object.fromEntries(species.map(s => [s.id, s]));
const out = new Map();

function place(s) {
  const base = s.baseSpeciesId && spById[s.baseSpeciesId];
  if (base) { // variant: inherit the base's line and stage
    const b = out.get(base.id) || place(base);
    return b && { speciesId: s.id, lineId: b.lineId, stage: b.stage, method: 'base' };
  }
  const rules = R[s.familyKey];
  if (!rules) return null; // kobold, floorborn, sandborne, humanoid_enemy: no bible group
  const n = norm(s.name);
  let line = null, method = 'family';
  for (const [re, g] of OVERRIDE) if (re.test(n) && g) { line = g; method = 'keyword'; break; }
  if (!line) for (let i = 0; i < rules.length; i++) if (rules[i][0].test(n)) { line = rules[i][1]; method = i < rules.length - 1 ? 'keyword' : 'family'; break; }
  const idx = stageIndex['evl_' + line] || new Map();
  let stage = idx.get(n);
  if (stage) method = 'name';
  else stage = rankStage(s.rank);
  return { speciesId: s.id, lineId: `evl_${line}`, stage, method };
}
// Bases first so variants can inherit.
for (const s of species.filter(x => !x.baseSpeciesId)) { const p = place(s); if (p) out.set(s.id, p); }
for (const s of species.filter(x => x.baseSpeciesId)) { const p = place(s); if (p) out.set(s.id, p); }

for (const p of out.values()) if (!byId[p.lineId]) throw new Error(`unknown line ${p.lineId} for ${p.speciesId}`);
const rows = species.filter(s => out.has(s.id)).map(s => out.get(s.id));
const unassigned = species.filter(s => !out.has(s.id)).map(s => s.id);
const counts = {}; rows.forEach(r => counts[r.method] = (counts[r.method] || 0) + 1);
const file = {
  notes: 'DRAFT side file: which evolution line and stage each species sits in. Generated by Tools/bestiary/assign_species_lines.js. method: name = the species name is a stage label; keyword = a name keyword chose the line, stage guessed from rank; family = the family default, stage guessed from rank; base = a variant inherits its base species. Stage-from-rank is a placement guess for review; threat rank is never inferred from stage. Unassigned species belong to game families the bible has no group for.',
  methods: counts, unassigned, assignments: rows
};
fs.writeFileSync(path.join(D, 'species_lines.json'), JSON.stringify(file, null, 1) + '\n');
console.log(`species_lines.json: ${rows.length} assigned, ${unassigned.length} unassigned`, JSON.stringify(counts));
const per = {}; rows.forEach(r => per[r.lineId] = (per[r.lineId] || 0) + 1);
console.log(JSON.stringify(per));
